+            {coin.ToV2Output()}, 0, 0, 0, std::nullopt, message, error), error);
+        uint256 entry;
+        cache.ComputeBip340Entry(entry, message,
+            tx.vin[0].vWitnesses[0].arguments[0],
+            std::span<const uint8_t>(program.data() + 1, 32), false);
+        return entry;
+    };
