+    auto child2 = MakeTransactionRef(NativeBenchmarkSpend(*tx, 0,
+        {tx->vout[0].nValue - 10001 * SATOSHI}));
+    const auto child2_entry = entry_for(*child2, tx->vout[0]);
+    warm(child2);
